/**
 * Handler for ContactTrigger.
 *
 * Keeps the original behaviour of the legacy trigger while making every
 * database operation bulk-safe. For any single trigger execution:
 *   - before context: 1 SOQL query
 *   - after context : 1 SOQL query
 *   - after context : 1 DML statement
 *
 * The class is declared "without sharing" because triggers execute in system
 * context; this preserves the original data visibility/behaviour.
 */
public without sharing class ContactTriggerHandler {

    /**
     * Before insert: default MailingCountry and LeadSource from the related Account.
     */
    public static void beforeInsert(List<Contact> newContacts) {
        Map<Id, Account> accountsById = getAccountDefaults(newContacts);

        for (Contact c : newContacts) {
            Account a = accountFor(c, accountsById);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * Before update: default MailingCountry from the related Account.
     * LeadSource is intentionally not touched on update, matching the old code.
     */
    public static void beforeUpdate(List<Contact> newContacts) {
        Map<Id, Account> accountsById = getAccountDefaults(newContacts);

        for (Contact c : newContacts) {
            Account a = accountFor(c, accountsById);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
        }
    }

    /**
     * After insert: if an Account has no Phone, seed it with the Phone of the
     * first Contact (in trigger order) for that Account that has a Phone.
     * All affected Accounts are updated in a single DML statement.
     */
    public static void afterInsert(List<Contact> newContacts) {
        Map<Id, Account> accountsById = getAccountPhones(newContacts);
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();

        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }

            Account a = accountsById.get(c.AccountId);
            if (a == null || String.isNotBlank(a.Phone)) {
                continue;
            }

            // First Contact (trigger order) with a Phone wins: once we set the
            // Phone on the in-memory Account, later Contacts are skipped above.
            a.Phone = c.Phone;
            accountsToUpdate.put(a.Id, a);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    /**
     * Queries the fields needed by the before context for every referenced Account.
     */
    private static Map<Id, Account> getAccountDefaults(List<Contact> contacts) {
        Set<Id> accountIds = collectAccountIds(contacts);
        if (accountIds.isEmpty()) {
            return new Map<Id, Account>();
        }
        return new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);
    }

    /**
     * Queries the Phone of every referenced Account for the after context.
     */
    private static Map<Id, Account> getAccountPhones(List<Contact> contacts) {
        Set<Id> accountIds = collectAccountIds(contacts);
        if (accountIds.isEmpty()) {
            return new Map<Id, Account>();
        }
        return new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);
    }

    /**
     * Returns the Account for a Contact, or null when there is no Account.
     */
    private static Account accountFor(Contact c, Map<Id, Account> accountsById) {
        return c.AccountId == null ? null : accountsById.get(c.AccountId);
    }

    /**
     * Collects the distinct, non-null Account ids referenced by the Contacts.
     */
    private static Set<Id> collectAccountIds(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        return accountIds;
    }
}
