/**
 * Scheduled job that purges FB_Integration_Log__c records to reclaim storage.
 *
 * Retention rules:
 *  - Regular logs (Level__c is not "ERROR", including blank) are deleted once
 *    they are more than 30 days old.
 *  - Error logs (Level__c = "ERROR") are retained until they are more than
 *    180 days old.
 *
 * The class runs in system mode (without sharing) so that the maintenance job
 * can remove every matching log regardless of the running user's sharing
 * access. Deletion is chunked and performed with allOrNone = false so a single
 * locked/failed record cannot abort the whole run.
 */
public without sharing class LogPurgeJob implements Schedulable {
    /** Retention window, in days, for non-error logs. */
    @TestVisible
    private static final Integer RETENTION_DAYS = 30;

    /** Retention window, in days, for logs whose Level__c is "ERROR". */
    @TestVisible
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Maximum number of records removed per transaction (DML row limit). */
    @TestVisible
    private static final Integer DELETE_BATCH_SIZE = 10000;

    /** No-argument constructor required for Schedulable / System.schedule. */
    public LogPurgeJob() {
    }

    /**
     * Deletes every log record that has exceeded its retention window.
     */
    public void execute(SchedulableContext sc) {
        DateTime standardCutoff = DateTime.now().addDays(-RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
               OR ((Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :standardCutoff)
            LIMIT :DELETE_BATCH_SIZE
        ];

        if (!logsToDelete.isEmpty()) {
            Database.delete(logsToDelete, false);
        }
    }

    /**
     * Schedules the purge to run every day at 02:00 under the job name
     * "Log purge (nightly)".
     *
     * @return the CronTrigger Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
```

Notes on the key decisions:

- **Retention logic** — The query deletes `ERROR` logs only past 180 days, and everything else (including blank/`null` `Level__c`) past 30 days. The explicit `Level__c = null` branch is required because SOQL `!=` does not match null values.
- **Bulk safety** — Deletion is capped at 10,000 records (the DML row limit) and uses `Database.delete(..., false)` for partial success, so one locked record cannot fail the run.
- **Sharing** — Declared `without sharing` (system mode) so a maintenance purge is not silently blocked by the scheduler's sharing access.
- **Cron** — `0 0 2 * * ?` = seconds `0`, minutes `0`, hour `2`, every day.

