/**
 * Pure unit tests for OpportunityForecastService.weightedAmountByStage(Set<Id>).
 *
 * These tests perform no DML and no SOQL. The IOpportunitiesSelector dependency is
 * replaced with an ApexMocks mock registered through Application.Selector, and the
 * Opportunity records are built in memory using fflib_IDGenerator fake ids.
 */
@IsTest
private class OpportunityForecastServiceTest {

    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_QUALIFICATION = 'Qualification';

    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector mockSelector;

    /**
     * Creates the mock selector and registers it with the application selector factory.
     */
    private static void registerSelectorMock() {
        mocks = new fflib_ApexMocks();
        mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);
    }

    /**
     * Stubs selectOpenByAccountIds(accountIds) to return the supplied opportunities.
     */
    private static void stubSelectOpenByAccountIds(Set<Id> accountIds, List<Opportunity> opportunities) {
        mocks.startStubbing();
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();
    }

    /**
     * Builds an in-memory Opportunity with a fake id. No DML is performed.
     */
    private static Opportunity buildOpportunity(Id accountId, String stageName, Decimal amount, Decimal probability) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            Name = 'Test Opportunity',
            AccountId = accountId,
            StageName = stageName,
            Amount = amount,
            Probability = probability,
            CloseDate = Date.today().addDays(30)
        );
    }

    @IsTest
    static void sumsWeightedAmountsPerStageRoundedPerOpportunity() {
        // Arrange
        registerSelectorMock();
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_PROSPECTING, 100, 33.333),
            buildOpportunity(accountId, STAGE_PROSPECTING, 100, 33.333),
            buildOpportunity(accountId, STAGE_QUALIFICATION, 1000, 12.3456)
        };
        stubSelectOpenByAccountIds(accountIds, opportunities);

        // Act
        Map<String, Decimal> weightedByStage = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Assert
        System.assertEquals(2, weightedByStage.size(), 'One aggregated value per stage is expected.');
        // Each opportunity is rounded to 2 decimals before summing: 33.33 + 33.33 = 66.66 (not 66.67).
        System.assertEquals(66.66, weightedByStage.get(STAGE_PROSPECTING),
            'Weighted amount must be rounded to 2 decimals per opportunity before summing.');
        System.assertEquals(123.46, weightedByStage.get(STAGE_QUALIFICATION),
            'Weighted amount must be rounded to 2 decimals per opportunity.');
    }

    @IsTest
    static void ignoresOpportunitiesWithoutAmountOrProbability() {
        // Arrange
        registerSelectorMock();
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_PROSPECTING, null, 50),
            buildOpportunity(accountId, STAGE_PROSPECTING, 100, null),
            buildOpportunity(accountId, STAGE_PROSPECTING, null, null),
            buildOpportunity(accountId, STAGE_QUALIFICATION, 200, 25)
        };
        stubSelectOpenByAccountIds(accountIds, opportunities);

        // Act
        Map<String, Decimal> weightedByStage = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Assert
        System.assertEquals(1, weightedByStage.size(),
            'Only opportunities with both Amount and Probability should be aggregated.');
        System.assert(!weightedByStage.containsKey(STAGE_PROSPECTING),
            'Opportunities missing Amount or Probability must be ignored.');
        System.assertEquals(50.00, weightedByStage.get(STAGE_QUALIFICATION),
            '200 * 25 / 100 = 50.00.');
    }

    @IsTest
    static void returnsEmptyMapWhenAccountIdsIsNull() {
        // Arrange: a sentinel is stubbed so the test fails if the selector is queried at all.
        registerSelectorMock();
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        stubSelectOpenByAccountIds(
            null,
            new List<Opportunity>{ buildOpportunity(accountId, STAGE_PROSPECTING, 100, 50) }
        );

        // Act
        Map<String, Decimal> weightedByStage = OpportunityForecastService.weightedAmountByStage(null);

        // Assert
        System.assert(weightedByStage.isEmpty(),
            'A null set of account ids must return an empty map without querying the selector.');
    }

    @IsTest
    static void returnsEmptyMapWhenAccountIdsIsEmpty() {
        // Arrange: a sentinel is stubbed so the test fails if the selector is queried at all.
        registerSelectorMock();
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>();
        stubSelectOpenByAccountIds(
            accountIds,
            new List<Opportunity>{ buildOpportunity(accountId, STAGE_PROSPECTING, 100, 50) }
        );

        // Act
        Map<String, Decimal> weightedByStage = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Assert
        System.assert(weightedByStage.isEmpty(),
            'An empty set of account ids must return an empty map without querying the selector.');
    }
}
