/**
 * Pure unit tests for OpportunityCleanupService.closeStale.
 *
 * These tests deliberately perform no DML and no SOQL. The selector and the
 * unit of work are replaced with ApexMocks test doubles that are injected
 * through the fflib Application factories, and fake record Ids are produced
 * with fflib_IDGenerator.
 *
 * The tests pin the service contract:
 *   - an opportunity is stale when its stage is neither 'Closed Won' nor
 *     'Closed Lost' and its CloseDate is strictly before the cutoff;
 *   - stale opportunities get StageName = 'Closed Lost' and
 *     Description = OpportunityCleanupService.LOST_REASON and are handed to
 *     registerDirty(SObject);
 *   - commitWork() runs exactly once when something was closed and never when
 *     nothing was closed;
 *   - the method returns the number of closed opportunities, and null or empty
 *     input returns 0.
 */
@isTest
private class OpportunityCleanupServiceTest {

    private static final Date CUTOFF = Date.newInstance(2024, 6, 1);

    private static fflib_ApexMocks mocks;
    private static fflib_IDGenerator idGenerator;
    private static IOpportunitiesSelector selectorMock;
    private static fflib_ISObjectUnitOfWork uowMock;

    // -------------------------------------------------------------------------
    // Test double setup and helpers
    // -------------------------------------------------------------------------

    private static void setupMocks() {
        mocks = new fflib_ApexMocks();
        idGenerator = new fflib_IDGenerator(15);

        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        // setMock() keys the mock by its SObjectType, so it must be stubbed first.
        mocks.startStubbing();
        mocks.when(selectorMock.getSObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);
    }

    private static void stubSelect(Set<Id> ids, List<Opportunity> records) {
        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(records);
        mocks.stopStubbing();
    }

    private static Opportunity buildOpportunity(String name, String stageName, Date closeDate) {
        return new Opportunity(
            Id = idGenerator.generate(Opportunity.SObjectType),
            Name = name,
            StageName = stageName,
            CloseDate = closeDate
        );
    }

    private static Set<Id> idsOf(List<Opportunity> records) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity record : records) {
            ids.add(record.Id);
        }
        return ids;
    }

    // -------------------------------------------------------------------------
    // Null / empty input
    // -------------------------------------------------------------------------

    @isTest
    static void returnsZeroForNullIds() {
        setupMocks();

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(null, CUTOFF);
        Test.stopTest();

        System.assertEquals(0, closed, 'Null ids must close nothing');
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @isTest
    static void returnsZeroForEmptyIds() {
        setupMocks();

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(new Set<Id>(), CUTOFF);
        Test.stopTest();

        System.assertEquals(0, closed, 'Empty ids must close nothing');
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    // -------------------------------------------------------------------------
    // Stale opportunities are closed
    // -------------------------------------------------------------------------

    @isTest
    static void closesStaleOpportunity() {
        setupMocks();

        Opportunity stale = buildOpportunity('Stale', 'Prospecting', CUTOFF.addDays(-1));
        List<Opportunity> records = new List<Opportunity>{ stale };
        Set<Id> ids = idsOf(records);
        stubSelect(ids, records);

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(ids, CUTOFF);
        Test.stopTest();

        System.assertEquals(1, closed, 'One stale opportunity must be closed');
        System.assertEquals('Closed Lost', stale.StageName, 'Stage must become Closed Lost');
        System.assertEquals(
            OpportunityCleanupService.LOST_REASON,
            stale.Description,
            'Description must carry the automatic close reason'
        );

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectById(ids);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(stale);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    @isTest
    static void closesEveryStaleOpportunityAndCommitsOnce() {
        setupMocks();

        Opportunity first = buildOpportunity('Stale A', 'Qualification', CUTOFF.addDays(-30));
        Opportunity second = buildOpportunity('Stale B', 'Needs Analysis', CUTOFF.addDays(-1));
        List<Opportunity> records = new List<Opportunity>{ first, second };
        Set<Id> ids = idsOf(records);
        stubSelect(ids, records);

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(ids, CUTOFF);
        Test.stopTest();

        System.assertEquals(2, closed, 'Both stale opportunities must be closed');
        for (Opportunity record : records) {
            System.assertEquals('Closed Lost', record.StageName);
            System.assertEquals(OpportunityCleanupService.LOST_REASON, record.Description);
        }

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(first);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(second);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    // -------------------------------------------------------------------------
    // Opportunities that must be left alone
    // -------------------------------------------------------------------------

    @isTest
