```apex
/**
 * Domain class for Opportunity.
 *
 * Validation rules:
 *  1. On insert and update, Amount must not be negative.
 *  2. On update, an Opportunity whose stage was already 'Closed Won' before the
 *     update cannot have its Amount changed. Closing an Opportunity as won and
 *     changing its Amount in the same update is allowed.
 *
 * Errors are raised through fflib_SObjectDomain.error(message, record, field) so
 * that they are placed on the Amount field of the offending record only and are
 * captured in fflib_SObjectDomain.Errors for unit tests.
 */
public with sharing class Opportunities extends fflib_SObjectDomain
{
    /**
     * Typed view over the records being processed.
     */
    private final List<Opportunity> opportunities;

    public Opportunities(List<SObject> sObjectList)
    {
        super(sObjectList);
        this.opportunities = (List<Opportunity>) sObjectList;
    }

    /**
     * Standard fflib domain constructor used by fflib_SObjectDomain.triggerHandler.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Called on before insert and before update.
     * Amount must not be negative.
     */
    public override void onValidate()
    {
        for(Opportunity opp : opportunities)
        {
            if(opp.Amount != null && opp.Amount < 0)
            {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    /**
     * Called on before update, with access to the existing (old) records.
     * An Opportunity that was already 'Closed Won' before the update cannot have
     * its Amount changed.
     */
    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        // Run the common validation (Amount must not be negative) for updates too.
        onValidate();

        if(existingRecords == null)
        {
            return;
        }

        for(Opportunity opp : opportunities)
        {
            // Only existing (already persisted) records can have a previous stage.
            if(opp.Id == null)
            {
                continue;
            }

            Opportunity existingOpp = (Opportunity) existingRecords.get(opp.Id);

            if(existingOpp == null)
            {
                continue;
            }

            if(existingOpp.StageName == 'Closed Won'
                && existingOpp.Amount != opp.Amount)
            {
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }
}
