 * Publishes Deal_Stage_Change__e platform events for Opportunities.
 *
 * The data warehouse subscribes to Deal_Stage_Change__e (publish after commit).
 * This class is intentionally bulk-safe: it builds the complete list of events
 * and issues a single EventBus.publish call, so a trigger handler passing up to
 * 200 Opportunities stays well inside the per-transaction DML statement limit.
 *
 * EventBus.publish(List<SObject>) returns one Database.SaveResult per event,
 * index-aligned with the input list, so callers can still tell exactly which
 * event failed and map it back to the source Opportunity.
 */
public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e event per Opportunity.
     *
     * @param opportunities Opportunities to publish. May be null or empty.
     * @return SaveResults in the same order as the input list; an empty list
     *         when there is nothing to publish.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            // opp.Id stringifies to the 18-character Id form.
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            ));
        }

        return EventBus.publish(events);
    }
}
