```apex
/**
 * AccountCountrySync
 *
 * When an Account's BillingCountry changes, the Contacts on that Account should
 * "follow" the move: their MailingCountry is set to the Account's new
 * BillingCountry when it is blank or was equal to the Account's previous
 * BillingCountry.
 *
 * Contacts with any other MailingCountry (people working abroad) are left alone,
 * as are Contacts of Accounts whose BillingCountry did not change.
 *
 * Bulk-safe: one selective SOQL query per trigger batch and one bulk DML.
 * There is no SOQL or DML inside any loop.
 */
public with sharing class AccountCountrySync {

    /**
     * @param newAccounts Trigger.newMap  - Accounts after the update.
     * @param oldAccounts Trigger.oldMap  - Accounts before the update.
     */
    public static void syncMailingCountry(Map<Id, Account> newAccounts, Map<Id, Account> oldAccounts) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccounts == null) {
            return;
        }

        // 1. Determine which Accounts actually changed BillingCountry in this batch.
        //    Accounts that were not updated, or whose country is unchanged, are ignored.
        Set<Id> changedAccountIds = new Set<Id>();
        for (Account acc : newAccounts.values()) {
            Account oldAcc = oldAccounts.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccountIds.add(acc.Id);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        // 2. A single selective query, scoped to the Accounts in this trigger batch.
        //    AccountId is indexed, so this stays far below governor limits even in an
        //    org with millions of Contacts. (Do NOT query the whole Contact table here:
        //    a query without a WHERE clause would hit the 50,000-row SOQL limit and the
        //    heap limit long before it returned.)
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            Account newAcc = newAccounts.get(con.AccountId);
            Account oldAcc = oldAccounts.get(con.AccountId);
            if (newAcc == null || oldAcc == null) {
                continue;
            }

            String previousCountry = oldAcc.BillingCountry;
            String newCountry = newAcc.BillingCountry;

            // The Contact follows the Account when its MailingCountry is blank or
            // was equal to the Account's previous BillingCountry.
            Boolean shouldFollow =
                String.isBlank(con.MailingCountry)
                || (previousCountry != null && con.MailingCountry == previousCountry);

            // Only enqueue Contacts that actually need a new value.
            if (shouldFollow && con.MailingCountry != newCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        // 3. One bulk DML statement for the whole batch.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
```

