import { LightningElement, api } from 'lwc';
import favoriteAdd from '@salesforce/label/c.Favorite_Add';
import favoriteRemove from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    // Backing value for the public `favorite` property. Kept separate so the
    // public API is never reassigned directly and the parent can push a new
    // value at any time (e.g. after a server refresh).
    _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        this._favorite = value === true;
    }

    // String values are required for aria-pressed ("true" / "false").
    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    // Label of the action a click performs: remove when favourited, add otherwise.
    get label() {
        return this._favorite ? favoriteRemove : favoriteAdd;
    }

    get iconVariant() {
        return this._favorite ? 'warning' : 'bare';
    }

    handleClick() {
        // Optimistic UI: flip immediately, then notify the parent.
        this._favorite = !this._favorite;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: this._favorite },
                bubbles: true,
                composed: true
            })
        );
    }
}
```

