```js
import { LightningElement, api } from 'lwc';

const NAVIGATION_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
const OPTION_ID_PREFIX = 'status-option-';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeValue;

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value : [];
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        // The parent changed the selection: move the active option to it.
        this._activeValue = value;
    }

    /**
     * The value of the currently active option. Falls back to the selected
     * value, then to the first option, so the list always has an active option
     * whenever it has options.
     */
    get activeValue() {
        const options = this._options;
        if (options.length === 0) {
            return undefined;
        }

        const exists = (candidate) =>
            options.some((option) => option.value === candidate);

        if (
            this._activeValue !== undefined &&
            this._activeValue !== null &&
            exists(this._activeValue)
        ) {
            return this._activeValue;
        }

        if (
            this._value !== undefined &&
            this._value !== null &&
            exists(this._value)
        ) {
            return this._value;
        }

        return options[0].value;
    }

    get activeDescendant() {
        const index = this._options.findIndex(
            (option) => option.value === this.activeValue
        );
        return index === -1 ? undefined : `${OPTION_ID_PREFIX}${index}`;
    }

    get renderedOptions() {
        const activeValue = this.activeValue;
        return this._options.map((option, index) => {
            const isActive = option.value === activeValue;
            return {
                id: `${OPTION_ID_PREFIX}${index}`,
                value: option.value,
                label: option.label,
                selected: option.value === this._value ? 'true' : 'false',
                className: isActive
                    ? 'status-listbox__option status-listbox__option_active'
                    : 'status-listbox__option',
            };
        });
    }

    handleKeyDown(event) {
        const { key } = event;

        // Only the six documented keys are consumed. Everything else (Tab,
        // typing, etc.) keeps its default behaviour.
        if (!NAVIGATION_KEYS.includes(key)) {
            return;
        }
        event.preventDefault();

        const options = this._options;
        if (options.length === 0) {
            return;
        }

        const currentIndex = options.findIndex(
            (option) => option.value === this.activeValue
        );

        switch (key) {
            case 'ArrowDown':
                this._activeValue =
                    options[Math.min(currentIndex + 1, options.length - 1)]
                        .value;
                break;
            case 'ArrowUp':
                this._activeValue =
                    options[Math.max(currentIndex - 1, 0)].value;
                break;
            case 'Home':
                this._activeValue = options[0].value;
                break;
            case 'End':
                this._activeValue = options[options.length - 1].value;
                break;
            case 'Enter':
            case ' ':
                this.selectValue(this.activeValue);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const optionElement = event.target.closest('li[role="option"]');
        if (!optionElement) {
            return;
        }

        // Resolve the option by position so the original value type is kept
        // (data-* attributes are always strings).
        const list = event.currentTarget;
        const items = Array.from(list.querySelectorAll('li[role="option"]'));
        const index = items.indexOf(optionElement);
        if (index === -1) {
            return;
        }

        this.selectValue(this._options[index].value);

        // Keep DOM focus on the list so keyboard navigation keeps working.
        list.focus();
    }

    selectValue(value) {
        // Clicking an already selected option still makes it active but must
        // not emit a change event.
        this._activeValue = value;
        if (value === this._value) {
            return;
        }

        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
            })
        );
    }
}
