  "orgName": "Pinnacle RevOps",
  "edition": "Enterprise",
  "features": ["TerritoryManagement2"],
  "settings": {
    "forecastsSettings": {
      "enableForecasts": true,
      "enableQuotas": true,
      "enableManagerAdjustment": true,
      "enableForecastCustomFields": true
    },
    "territory2Settings": {
      "enableTerritoryManagement2": true
    },
