```apex
/**
 * Trigger Action that collects the Ids of the Opportunities which have to be pushed to the ERP.
 *
 * It runs in the after insert and after update contexts. A single DML operation can be split into
 * several trigger chunks (e.g. 200 + 50 for a 250 record insert), so the Ids are accumulated in a
 * static collection owned by OpportunityErpSyncFinalizer and TriggerBase.waitToFinalize() is used
 * to request that the finalizer runs once, after the whole DML operation has been processed.
 */
public with sharing class TA_Opportunity_CollectForErpSync
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    public void afterInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            OpportunityErpSyncFinalizer.collect(record.Id);
        }
        TriggerBase.waitToFinalize();
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        for (Integer index = 0; index < triggerNew.size(); index++) {
            Opportunity newOpportunity = (Opportunity) triggerNew[index];
            Opportunity oldOpportunity = (Opportunity) triggerOld[index];
            if (newOpportunity.StageName != oldOpportunity.StageName) {
                OpportunityErpSyncFinalizer.collect(newOpportunity.Id);
            }
        }
        TriggerBase.waitToFinalize();
    }
}
