```apex
/**
 * DML Finalizer that enqueues exactly one OpportunityErpSyncJob per DML operation.
 *
 * TA_Opportunity_CollectForErpSync accumulates the Ids that need syncing in the static collection
 * below. The framework invokes every registered finalizer at the end of every DML operation it
 * handles, whatever the sObject, so this finalizer simply does nothing when no Opportunity Ids
 * were collected. Finalizers must not perform DML, therefore this class only enqueues a Queueable.
 */
public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
    @TestVisible
    private static final Set<Id> opportunityIdsToSync = new Set<Id>();

    /**
     * Adds an Opportunity Id to the set of records that must be synced by the current DML
     * operation.
     */
    public static void collect(Id opportunityId) {
        if (opportunityId != null) {
            opportunityIdsToSync.add(opportunityId);
        }
    }

    public void execute(FinalizerHandler.Context context) {
        if (opportunityIdsToSync.isEmpty()) {
            return;
        }
        // Take a copy and reset the collection so that a later DML operation in the same
        // transaction starts from a clean slate and enqueues its own job.
        Set<Id> idsToSync = new Set<Id>(opportunityIdsToSync);
        opportunityIdsToSync.clear();
        System.enqueueJob(new OpportunityErpSyncJob(idsToSync));
    }
}
